<?php $title='Uporabniki'; require_once '../includes/functions.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); $id=(int)$_POST['id']; if($id!==user()['id']){ if($_POST['a']==='vloga') db()->prepare("UPDATE uporabniki SET vloga=IF(vloga='admin','uporabnik','admin') WHERE id=?")->execute([$id]); else db()->prepare('DELETE FROM uporabniki WHERE id=?')->execute([$id]); flash('Shranjeno.'); } redirect('admin/uporabniki.php'); }
