<h1>Uporabniki</h1><div class="tw"><table><tr><th>Ime</th><th>E-naslov</th><th>Vloga</th><th></th></tr><?php foreach($r as $x): ?><tr><td><?=e($x['ime'].' '.$x['priimek'])?></td><td><?=e($x['email'])?></td><td><?=$x['vloga']?></td><td><?php if($x['id']!=user()['id']): foreach(['vloga'=>'Zamenjaj vlogo','briši'=>'Izbriši'] as $a=>$l): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="a" value="<?=$a?>"><button class="<?=$a==='briši'?'red':'gray'?>" <?=$a==='briši'?'data-confirm="Izbrišem uporabnika?"':''?>><?=$l?></button></form> <?php endforeach; endif; ?></td></tr><?php endforeach; ?></table></div>
